.diamond-card {
  width: 220px; height: 300px;
  background: rgba(255, 255, 255, 0.05); backdrop-filter: blur(15px);
  border: 1px solid rgba(255, 255, 255, 0.2); border-radius: 15px;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  box-shadow: 0 20px 40px rgba(0,0,0,0.5);
  transition: transform 0.4s ease, box-shadow 0.4s ease; cursor: pointer;
  color: #fff; font-family: sans-serif;
}
.diamond-card:hover {
  transform: translateY(-10px);
  box-shadow: 0 30px 60px rgba(0, 255, 255, 0.3);
  border-color: rgba(0, 255, 255, 0.5);
}
.diamond-svg {
  width: 80px; height: 80px; margin-bottom: 20px;
  filter: drop-shadow(0 0 10px rgba(0, 255, 255, 0.8));
}
.diamond-path {
  fill: none; stroke: #00ffff; stroke-width: 2;
  stroke-dasharray: 300; stroke-dashoffset: 300;
  animation: drawDiamond 3s ease-out forwards infinite alternate;
}
@keyframes drawDiamond { to { stroke-dashoffset: 0; } }
